mapper.update:
UPDATE TB_CHCF001
   SET CONF_VAL    = #{c.configValue},
       READONLY_YN = #{c.readonlyYn},
       UPD_DT      = NOW()
 WHERE CP_ID    = #{c.cpId}
   AND CS_ID    = #{c.csId}
   AND CONF_KEY = #{c.configKey}

mapper.select:
SELECT CP_ID, CS_ID, CONF_KEY, CONF_VAL, READONLY_YN, UPD_DT
  FROM TB_CHCF001
 WHERE CP_ID    = #{cpId}
   AND CS_ID    = #{csId}
   AND CONF_KEY = #{configKey}
 LIMIT 1

SELECT CP_ID, CS_ID, CONF_KEY, CONF_VAL, READONLY_YN, UPD_DT
  FROM TB_CHCF001
 WHERE CP_ID = #{cpId}
   AND CS_ID = #{csId}
 ORDER BY CONF_KEY

mapper.delete:
DELETE FROM TB_CHCF001
 WHERE CP_ID = #{cpId}
   AND CS_ID = #{csId}

DELETE FROM TB_CHCF001
 WHERE CP_ID    = #{cpId}
   AND CS_ID    = #{csId}
   AND CONF_KEY = #{configKey}
